const $=id=>document.getElementById(id), make=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const elements={1:'Neutral',2:'Water',3:'Fire',4:'Grass',5:'Electric',6:'Earth'};
const art=(src,alt,cls)=>{const n=make('img',undefined,cls);n.src=new URL(src.replace(/^\//,''),import.meta.url);n.alt=alt;n.loading='lazy';return n;};
let data,selected,category='normal',mode='skills';
function link(){const u=new URL(location.href);u.searchParams.set('zobo',selected.id);u.searchParams.set('mode',mode);history.replaceState(null,'',u);}
function roster(){const q=$('zobo-search').value.toLocaleLowerCase().trim(),element=$('zobo-element').value;const list=data.units.filter(u=>u.boss===(category==='boss')&&(!element||String(u.element)===element)&&u.name.toLocaleLowerCase().includes(q));$('roster-count').textContent=list.length+' '+(category==='boss'?(list.length===1?'boss':'bosses'):'normal Zobo');$('normal-zobo').setAttribute('aria-pressed',String(category==='normal'));$('boss-zobo').setAttribute('aria-pressed',String(category==='boss'));$('zobo-roster').replaceChildren(...list.map(u=>{const b=make('button',undefined,'roster-card zobo-roster-card');b.type='button';b.setAttribute('aria-label','Show '+u.name);b.setAttribute('aria-pressed',String(u.id===selected.id));b.append(art(u.icon,'','roster-portrait'),make('span',u.name),make('small',elements[u.element]));b.onclick=()=>{selected=u;render();roster();link();};return b;}));if(!list.length)$('zobo-roster').append(make('p','No Zobo matches these filters.','roster-empty'));}
function render(){const u=selected,header=make('div',undefined,'zobo-profile-header'),info=make('div');info.append(make('p',(u.boss?'Zobo Boss':'Normal Zobo')+' · '+elements[u.element],'zobo-eyebrow'),make('h2',u.name),make('p',u.description||'No overview is recorded for this Zobo.','zobo-description'));header.append(art(u.icon,u.name,'zobo-portrait'),info);const stats=make('div',undefined,'zobo-stats');for(const a of ['ATK','HP','DEF']){const c=make('div',undefined,'zobo-stat');c.append(make('span',a+' growth'),make('strong','×'+u.growth[a]));stats.append(c);}const baseline=make('details',undefined,'zobo-stat-explanation');baseline.append(make('summary','What do these stats mean?'),make('p',data.notes.stats));$('zobo-profile').replaceChildren(header,stats,baseline);if(u.lore){const lore=make('details',undefined,'zobo-lore');lore.append(make('summary','About '+u.name),make('p',u.lore));$('zobo-profile').append(lore);}renderSkills();}
function renderSkills(){for(const [id,value] of [['shared-skills','skills'],['horde-skills','horde']])$(id).setAttribute('aria-pressed',String(mode===value));$('mode-note').hidden=mode!=='horde';$('mode-note').textContent=(selected.horde.recorded?'Recorded in the Horde Season 3 wave data. ':'Not listed in the audited Horde Season 3 waves. ')+data.notes.horde;$('zobo-skills').replaceChildren(...selected.skills.map((s,i)=>{const card=make('article',undefined,'skill-card zobo-skill-card'),heading=make('div',undefined,'zobo-skill-heading');heading.append(make('span',String(i+1).padStart(2,'0'),'zobo-skill-number'),make('h3',s.name));card.append(heading,make('p',s.description,'skill-description'));if(s.translation==='companion summary')card.append(make('small','Companion summary · helper skill','zobo-summary-label'));const dl=make('dl',undefined,'zobo-values');for(const [label,value] of s.details){const row=make('div');row.append(make('dt',label),make('dd',value));dl.append(row);}card.append(dl);for(const f of s.effects){const box=make('div',undefined,'zobo-effect');box.append(make('strong',f.name));if(f.duration)box.append(make('span',f.duration+' s duration'));for(const change of f.changes)box.append(make('span',change));if(f.stackable)box.append(make('span','Stackable'+(f.maxStacks>0?' · up to '+f.maxStacks+' stacks':'')));card.append(box);}if(s.targetGrid.length||s.areaGrid.length){const d=make('details',undefined,'zobo-range');d.append(make('summary','Attack area'));for(const [label,values] of [['Target offsets',s.targetGrid],['Area offsets',s.areaGrid]])if(values.length)d.append(make('p',label+': '+values.map(v=>typeof v==='object'?Object.values(v).join(', '):v).join(' · ')));card.append(d);}return card;}));}
function setCategory(value){category=value;$('zobo-search').value='';$('zobo-element').value='';selected=data.units.find(u=>u.boss===(category==='boss'));render();roster();link();}
for(const [id,value] of [['normal-zobo','normal'],['boss-zobo','boss']]){$(id).onclick=()=>setCategory(value);$(id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setCategory(e.key==='Home'?'normal':e.key==='End'?'boss':category==='boss'?'normal':'boss');$(category==='boss'?'boss-zobo':'normal-zobo').focus();}};}
for(const [id,value] of [['shared-skills','skills'],['horde-skills','horde']])$(id).onclick=()=>{mode=value;renderSkills();link();};
$('zobo-search').oninput=roster;$('zobo-element').onchange=roster;
try{const response=await fetch(new URL('./zobo-data.json',import.meta.url));if(!response.ok)throw Error('Unable to load Zobo data.');data=await response.json();const params=new URL(location.href).searchParams;selected=data.units.find(u=>u.id===Number(params.get('zobo')))||data.units[0];category=selected.boss?'boss':'normal';mode=params.get('mode')==='horde'?'horde':'skills';roster();render();$('database-status').textContent='';}catch(error){$('database-status').textContent='Could not load the database. Please reload the page.';console.error(error);}
